  for (const [i, d] of DRONES.entries()) {
    d.legs = d.route.map((p, k) => { const q = d.route[(k + 1) % d.route.length]; return { p, q, len: deg2m(q[0] - p[0], q[1] - p[1], p[1]) }; });
    d.total = d.legs.reduce((s, l) => s + l.len, 0);
    d.s = d.total * ((i * 0.23) % 1); d.speed = 24 + i * 2;   // m/s
    d.alt = 180 + i * 35; d.batt = 92 - i * 7; d.rssi = -58 - i * 3; d.hist = { sats: [], hacc: [], alt: [], rssi: [], batt: [] };
    d.nav = 'GNSS'; d.events = []; d.gstate = 'NORMAL'; d.cell = null; d.airborne = true;
  }
  const events = [];   // newest first
  const listeners = [];
  const push = (e) => { e.ts = e.ts || now(); events.unshift(e); if (events.length > 200) events.pop(); for (const d of DRONES) if (e.drone === d.id) { d.events.unshift(e); d.events.length > 40 && d.events.pop(); } return e; };

  // seed history (what happened before the page opened)
  [
    [-44, 'pipeline', 'WF1', 'COLLECT CYCLE', '312 aircraft from adsb.lol, 41 cells written', 'observations stored, WF2 started'],
    [-41, 'agent', 'WF2', 'OPEN JAMMED 54.0_22.5', 'JAMMED 54.0_22.5 high: 10/14 aircraft degraded, 2 checks in a row', 'incident #47 open, sorties through 54.0_22.5 go to the gate'],
    [-41, 'agent', 'WF3', 'RESCHEDULE S-017', 'JAMMED cell 54.0_22.5 (high); routine, +2 h still inside its window', 'launch 22:30→00:30 UTC, sheet RESCHEDULED, FYI sent'],
    [-41, 'agent', 'WF3', 'CANCEL S-018', 'JAMMED cell 54.0_22.5 (high); low priority', 'sheet CANCELLED, FYI sent'],
    [-41, 'agent', 'WF3', 'HOLD S-019', 'JAMMED cell 54.0_22.5 (high); priority sortie, a human decides', 'sheet HOLD, card sent, awaiting duty officer'],
    [-33, 'drone', 'WF7', 'INGEST DRONE REPORT S-015', 'BG-UAV-12: 59.0_27.5 SPOOF 0/120 degraded (61 spoof-flag samples)', '1 cell report stored', 'BG-UAV-12'],
    [-30, 'agent', 'WF2', 'OPEN SPOOF 59.0_27.5', 'SPOOF 59.0_27.5 high: drone BG-UAV-12: receiver spoofing flag on 61/120', 'incident #51 open, sorties through 59.0_27.5 go to the gate'],
    [-30, 'agent', 'WF3', 'HOLD S-020', 'SPOOF cell 59.0_27.5 (high); possible spoofing, always a human call', 'sheet HOLD, card sent, awaiting duty officer'],
    [-26, 'pipeline', 'WF4', 'SWITCH SOURCE TO ADSB.FI', 'primary adsb.lol unavailable (HTTP 503), switched to adsb.fi', '288 aircraft from adsb.fi, 39 cells written'],
    [-19, 'human', 'WF6', 'KEEP HOLD S-020', 'duty officer tapped Keep HOLD: SPOOF cell 59.0_27.5 (high)', 'sheet stays HOLD'],
    [-12, 'agent', 'WF3', 'FLAG UNVERIFIED S-022', 'no sensor coverage in 55.0_26.0; launch in 48 min', 'nothing changed, officer notified'],
    [-6, 'agent', 'WF3', 'WATCH S-024', 'JAMMED cell 54.5_22.0 (medium); launch in 4 h', 'at risk, logged once; nothing changed'],
  ].forEach(([m, kind, wf, action, reason, outcome, drone]) => events.push({ ts: at(m), kind, wf, action, reason, outcome, drone }));
  events.sort((a, b) => b.ts - a.ts);

  const SORTIES = [
    ...DRONES.map((d, i) => ({ id: d.sortie, drone: d.id, unit: d.unit, priority: ['priority', 'routine', 'routine', 'priority', 'routine', 'low'][i], launch: at(-50 + i * 6), window: at(200), status: 'IN FLIGHT', level: null, reason: 'launched before the incident; AirGuard gates launches only' })),
    { id: 'S-017', drone: null, unit: 'LT · Lazdijai', priority: 'routine', launch: at(170), window: at(420), status: 'RESCHEDULED', level: 'L1_RESCHEDULE', reason: 'JAMMED 54.0_22.5 high: moved +2 h 22:30→00:30 UTC', cells: ['54.0_22.5', '54.0_23.0'] },
    { id: 'S-018', drone: null, unit: 'LT · Lazdijai', priority: 'low', launch: at(65), window: at(245), status: 'CANCELLED', level: 'L2_CANCEL', reason: 'JAMMED 54.0_22.5 high; low priority (training)', cells: ['54.0_22.5'] },
    { id: 'S-019', drone: 'BG-UAV-10', unit: 'LT · Lazdijai', priority: 'priority', launch: at(52), window: at(110), status: 'HOLD', level: 'L3_HOLD', reason: 'JAMMED 54.0_23.0 high; priority sortie, a human decides', cells: ['54.0_23.0'], pending: true },
    { id: 'S-020', drone: 'BG-UAV-15', unit: 'EE · Narva', priority: 'low', launch: at(75), window: at(255), status: 'HOLD', level: 'L4_SPOOF_HOLD', reason: 'SPOOF 59.0_27.5 high; kept on HOLD by the duty officer 21:21', cells: ['59.0_27.5'] },
    { id: 'S-021', drone: null, unit: 'LV · Latgale', priority: 'routine', launch: at(95), window: at(455), status: 'PLANNED', level: null, reason: 'no known issue on the route (drone report 56.0_27.5, 9 min ago)', cells: ['56.0_27.5', '56.5_27.5'] },
    { id: 'S-022', drone: null, unit: 'LT · Šalčininkai', priority: 'routine', launch: at(48), window: at(408), status: 'PLANNED', level: 'UNVERIFIED', reason: 'no sensor coverage in 55.0_26.0', cells: ['54.5_25.5', '55.0_26.0'] },
    { id: 'S-023', drone: null, unit: 'EE · Värska', priority: 'priority', launch: at(130), window: at(190), status: 'PLANNED', level: null, reason: 'no known issue on the route', cells: ['57.5_27.0', '58.0_27.0'] },
