    { id: 'S-025', drone: null, unit: 'LV · Latgale', priority: 'low', launch: at(330), window: at(510), status: 'PLANNED', level: null, reason: 'no known issue on the route', cells: ['56.5_27.5'] },
    { id: 'S-026', drone: null, unit: 'EE · Narva', priority: 'routine', launch: at(420), window: at(780), status: 'PLANNED', level: 'WATCH', reason: 'SPOOF 59.0_27.5 high; launch in 7 h', cells: ['59.0_27.5', '59.0_28.0'] },
    { id: 'S-027', drone: null, unit: 'LT · Pagėgiai', priority: 'priority', launch: at(560), window: at(620), status: 'PLANNED', level: null, reason: 'no known issue on the route', cells: ['55.0_21.5'] },
  ];
  const PENDING = [{ sortie: 'S-019', level: 'L3_HOLD', drone: 'BG-UAV-10', text: '⛔ HOLD · S-019 · LT Border Guard · Lazdijai · launch 23:32', line: 'JAMMED 54.0_23.0 (high): 7/9 aircraft degraded, 2 checks in a row', since: at(-41) }];

  // aircraft (the ADS-B sensor network)
  const AIR = Array.from({ length: 46 }, (_, i) => {
    const r = (k) => { const x = Math.sin(i * 97.13 + k * 13.7) * 43758.5453; return x - Math.floor(x); };
    return { hex: (0x4b1a00 + i * 2749).toString(16), lat: 53.8 + r(1) * 6.8, lon: 17.8 + r(2) * 9.8, hdg: r(3) * 360, alt: 30000 + (r(4) * 12 | 0) * 1000 };
  });

  const pipeline = { source: 'adsb.fi', aircraft: 288, cells: 39, lastRun: at(-1.5), failover: true, nextCycle: 0, rows: 18231, tgPending: PENDING.length, wf: { WF1: 'ok', WF2: 'ok', WF3: 'ok', WF4: 'ok', WF5: 'idle', WF6: 'ok', WF7: 'ok' } };

  let tick = 0;
  function step() {
    tick++;
    const t = now(), dt = SPEED;
    for (const d of DRONES) {
      d.s = (d.s + d.speed * dt) % d.total;
      let s = d.s, leg = d.legs[0];
      for (const l of d.legs) { if (s <= l.len) { leg = l; break; } s -= l.len; }
      const f = leg.len ? s / leg.len : 0;
      d.lon = leg.p[0] + (leg.q[0] - leg.p[0]) * f; d.lat = leg.p[1] + (leg.q[1] - leg.p[1]) * f;
      d.hdg = (Math.atan2((leg.q[0] - leg.p[0]) * Math.cos(d.lat * Math.PI / 180), leg.q[1] - leg.p[1]) * 180 / Math.PI + 360) % 360;
      const c = cellAt(d.lat, d.lon), st = c ? c.state : 'UNKNOWN', w = Math.sin(tick * 0.7 + d.speed);
      d.alt = Math.max(90, d.alt + w * 3); d.batt = Math.max(8, d.batt - 0.035 * dt / 15); d.rssi = -60 + w * 6 - (st === 'JAMMED' ? 14 : 0);
      if (st === 'JAMMED') Object.assign(d, { fix: Math.random() < 0.7 ? (Math.random() * 3 | 0) : 3, sats: Math.random() * 6 | 0, hacc: 14 + Math.random() * 60, jam: Math.random() < 0.7 ? 3 : 2, spoof: 1, gap: 0 });
      else if (st === 'SPOOF') Object.assign(d, { fix: 3, sats: 13 + (Math.random() * 3 | 0), hacc: 0.6 + Math.random() * 0.6, jam: 1, spoof: Math.random() < 0.8 ? 2 : 3, gap: 380 + Math.random() * 500 });
      else Object.assign(d, { fix: 3, sats: 11 + (Math.random() * 6 | 0), hacc: 0.9 + Math.random() * 1.6, jam: 1, spoof: 1, gap: 2 + Math.random() * 6 });
      const g = st === 'JAMMED' ? 'JAMMED' : st === 'SPOOF' ? 'SPOOF' : 'NORMAL';
      if (g !== d.gstate) {
        if (g === 'JAMMED') { d.nav = 'INS + optical flow'; push({ kind: 'drone', wf: 'AUTOPILOT', drone: d.id, action: `GNSS DEGRADED ${d.id}`, reason: `entered ${c.id}: ${d.sats} sats, h_acc ${d.hacc.toFixed(0)} m, jamming flag CRITICAL`, outcome: 'EKF rejected GNSS, navigating on INS + optical flow' }); }
        else if (g === 'SPOOF') { d.nav = 'INS (GNSS rejected)'; push({ kind: 'drone', wf: 'AUTOPILOT', drone: d.id, action: `GNSS SPOOF SUSPECTED ${d.id}`, reason: `entered ${c.id}: confident fix but GNSS/INS gap ${d.gap.toFixed(0)} m, spoofing flag INDICATED`, outcome: 'GNSS rejected, holding course on INS' }); }
        else { d.nav = 'GNSS'; push({ kind: 'drone', wf: 'AUTOPILOT', drone: d.id, action: `GNSS RESTORED ${d.id}`, reason: `left ${d.cell || 'the bad cell'}: ${d.sats} sats, h_acc ${d.hacc.toFixed(1)} m`, outcome: 'GNSS back in the navigation solution' }); }
        d.gstate = g;
      }
      d.cell = c ? c.id : cid(d.lat, d.lon);
      for (const [k, v] of [['sats', d.sats], ['hacc', d.hacc], ['alt', d.alt], ['rssi', d.rssi], ['batt', d.batt]]) { d.hist[k].push(v); if (d.hist[k].length > HIST) d.hist[k].shift(); }
    }
    for (const a of AIR) { const r = a.hdg * Math.PI / 180; a.lat += Math.cos(r) * 0.02; a.lon += Math.sin(r) * 0.035; if (a.lat > R.lat1 || a.lat < R.lat0 || a.lon > 27.8 || a.lon < R.lon0) { a.lat = 54 + Math.random() * 6; a.lon = a.hdg > 180 ? 27 : 18.2; } const c = cellAt(a.lat, a.lon); a.bad = c && c.state === 'JAMMED'; }
    pipeline.nextCycle = 30 - (tick % 30);
    if (tick % 30 === 0) {
      pipeline.lastRun = t; pipeline.aircraft = 280 + (Math.random() * 40 | 0); pipeline.cells = 38 + (Math.random() * 5 | 0); pipeline.rows += pipeline.cells;
      push({ kind: 'pipeline', wf: 'WF1', action: 'COLLECT CYCLE', reason: `${pipeline.aircraft} aircraft from ${pipeline.source}, ${pipeline.cells} cells written`, outcome: 'observations stored, WF2 → WF3 ran, no new incident' });
    }
    if (tick % 20 === 10) {
      const d = DRONES[(tick / 20 | 0) % DRONES.length];
      push({ kind: 'drone', wf: 'WF7', drone: d.id, action: `INGEST DRONE REPORT ${d.sortie}`, reason: `${d.id}: ${d.cell} ${d.gstate} ${d.gstate === 'JAMMED' ? '71' : '0'}/120 degraded`, outcome: '1 cell report stored; WF2 weighs it at the next cycle' });
    }
    for (const f of listeners) f(t);
  }
  // warm up the histories
  for (let i = 0; i < HIST; i++) { const keep = events.length; step(); events.splice(0, events.length - keep); for (const d of DRONES) d.events.length = 0; }
  for (const e of events) for (const d of DRONES) if (e.drone === d.id) d.events.push(e);
  tick = 0;
  setInterval(step, 1000);

  const fmt = {
    utc: (d) => d.toISOString().slice(11, 16) + 'Z',
    local: (d) => d.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', timeZone: 'Europe/Vilnius' }),
    ago: (d) => { const m = Math.round((now() - d) / 60e3); return m <= 0 ? 'now' : m < 60 ? `${m} min ago` : `${Math.floor(m / 60)} h ${m % 60} min ago`; },
    until: (d) => { const m = Math.round((d - now()) / 60e3); return m < 0 ? `${-m} min ago` : m < 60 ? `in ${m} min` : `in ${Math.floor(m / 60)} h ${m % 60} min`; },
    fixName: (f) => ['NO GPS', 'NO FIX', '2D FIX', '3D FIX'][f] || 'RTK',
    jamName: (j) => ['UNKNOWN', 'OK', 'WARNING', 'CRITICAL'][j],
    spoofName: (s) => ['UNKNOWN', 'NONE', 'INDICATED', 'MULTIPLE'][s],
  };
