function localTimes(text, writtenAt, tz) {
  const ref = Date.parse(writtenAt);
  if (!text || !Number.isFinite(ref)) return text;
  const hm = new Intl.DateTimeFormat('en-GB', { timeZone: tz, hour: '2-digit', minute: '2-digit' });
