 66	    const pts = data.map((v, i) => [i / (data.length - 1) * w, h - 2 - ((v - min) / sp) * (h - 4)]);
 67	    c.beginPath(); pts.forEach(([x, y], i) => c[i ? 'lineTo' : 'moveTo'](x, y)); c.lineTo(w, h); c.lineTo(0, h); c.closePath();
